package com.data_structures.stack;import java.io.PrintStream;import java.util.NoSuchElementException;/** * Defines the operations of a generic stack. * * @param <T> the type of elements stored in the stack */public interface StackInt<T> {	/**	 * Returns whether the stack contains no elements.	 *	 * @return true if the stack is empty	 */	boolean isEmpty();	/**	 * Inserts an element at the top of the stack.	 *	 * @param item element to insert	 */	void push(T item);	/**	 * Removes and returns the element at the top of the stack.	 *	 * @return the removed top element	 * @throws NoSuchElementException if the stack is empty	 */	T pop() throws NoSuchElementException;	/**	 * Returns the top element without removing it.	 *	 * @return the element at the top of the stack	 * @throws NoSuchElementException if the stack is empty	 */	T peek() throws NoSuchElementException;	/**	 * Prints the elements from the top of the stack to the supplied stream.	 *	 * @param stream destination output stream	 */	void printStack(PrintStream stream);	/**	 * Returns the number of elements currently in the stack.	 *	 * @return stack size	 */	int size();}